QuarticQuery.Construction.LocalTests/Qua.type:
∀ {κ : Type} {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
  {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)},
  QuarticQuery.addressedF f C ℓ r x = Bool.true ↔ ∃ i s, QuarticQuery.WinsAt f C ℓ r x i s

∀ {κ : Type} {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
  {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)} {i : QuarticQuery.Column ℓ}
  {s : QuarticQuery.Address r}, QuarticQuery.WinsAt f C ℓ r x i s ↔ QuarticQuery.PaperWinsAt f C ℓ r x i s

QuarticQuery.Construction.Winner/Quartic.type:
∀ {κ : Type} {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
  {x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)} {i i' : QuarticQuery.Column ℓ}
  {s s' : QuarticQuery.Address r},
  QuarticQuery.WinsAt f C ℓ r x i s → QuarticQuery.WinsAt f C ℓ r x i' s' → i = i' ∧ s = s'

QuarticQuery.Paper.ConstructionDefinitio.type:
∀ {κ : Type} {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
  (x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)) (i j : QuarticQuery.Column ℓ),
  QuarticQuery.Paper.constructionWinner f C ℓ r x i → QuarticQuery.Paper.constructionWinner f C ℓ r x j → i = j

∀ {κ : Type} {f : QuarticQuery.PartialBool κ} {C : QuarticQuery.Circuit κ} {ℓ r : ℕ}
  (x : QuarticQuery.BitInput (QuarticQuery.BitLoc ℓ r C.size κ)) (i : QuarticQuery.Column ℓ),
  QuarticQuery.Paper.constructionWinner f C ℓ r x i ↔ ∃ s, QuarticQuery.WinsAt f C ℓ r x i s
